-- 03_policy_snapshot.json (2026-09-23) 기준 seed. 수치를 바꿀 땐 새 행을 insert 하면 앱이 최신 행을 읽는다.
insert into public.policy_snapshot (updated_at, headline, items, params, regulated) values (
  date '2026-09-23',
  $txt$수도권·규제지역은 LTV·DSR·주택가격별 한도가 겹쳐 적용되는 구조가 그대로 유지되고 있어요. 8·13 금융 종합대책은 규제 비율은 두고 실수요자 지원을 조금 넓힌 쪽이에요.$txt$,
  $json$[{"date":"2026-07-01","impact":"분당·수지·기흥이 모두 규제지역이라 이 일대 아파트는 LTV 40%(생애최초 70%)와 실거주 의무를 전제로 계획해야 해요.","source":"국토교통부 보도참고자료","summary":"세 곳이 투기과열지구·조정대상지역으로 새로 묶였고, 토지거래허가구역 효력은 7월 5일부터 2027년 말까지예요. 이로써 규제지역은 서울 25개 구 전체와 경기 15곳이 됐어요.","tag":"규제지역","title":"화성 동탄구·용인 기흥구·구리시 규제지역 추가","url":"https://www.molit.go.kr/USR/NEWS/m_71/dtl.jsp?id=95092167"},{"date":"2025-10-15","impact":"입주 전에 미리 사두고 전세를 놓는 방식은 어려워요. 잔금·입주 시점을 맞춰 매수하는 흐름으로 잡는 게 현실적이에요. 이 토허구역 지정 기한(2026년 말) 연장 여부도 지켜봐야 해요.","source":"대한민국 정책브리핑","summary":"서울 전 자치구와 과천, 광명, 성남 분당·수정·중원, 수원 영통·장안·팔달, 안양 동안, 용인 수지, 의왕, 하남이 규제지역으로 지정됐어요. 해당 지역 아파트는 토지거래허가 대상이 되어 전세를 끼고 사는 방식이 막혔어요.","tag":"규제지역","title":"10·15 대책: 서울 전역·경기 12곳 규제지역 및 토지거래허가구역","url":"https://www.korea.kr/news/policyNewsView.do?newsId=148950973"},{"date":"2025-10-15","impact":"15억 이하 집이라면 대출 상한은 6억이에요. 자금 탭은 이 상한을 자동으로 반영해요.","source":"대한민국 정책브리핑","summary":"LTV·DSR을 모두 통과해도 시가 15억 이하는 6억, 15억 초과~25억은 4억, 25억 초과는 2억까지만 빌릴 수 있어요. 생애최초 구입자도 똑같이 적용돼요.","tag":"대출 한도","title":"수도권·규제지역 주담대 주택가격별 상한","url":"https://www.korea.kr/news/policyNewsView.do?newsId=148950973"},{"date":"2025-10-15","impact":"맞벌이 소득이 높아도 DSR 한도가 가장 먼저 걸릴 수 있어요. 금리 입력을 바꿔가며 확인해보세요.","source":"금융위원회 주요정책문답","summary":"DSR을 계산할 때 실제 금리에 얹는 스트레스 금리가 수도권·규제지역 주담대에서 1.5%p에서 3%p로 올라갔어요. 은행권 DSR 한도는 40%예요.","tag":"DSR","title":"수도권·규제지역 주담대 스트레스 금리 3%p","url":"https://www.fsc.go.kr/po020201/85518?srchCtgry=&curPage=&srchKey=&srchText=&srchBeginDt=&srchEndDt="},{"date":"2025-06-27","impact":"입주 목표 시점과 잔금일을 6개월 안으로 맞춰야 해요.","source":"금융위원회 보도자료","summary":"6·27 대책 이후 수도권·규제지역에서 집을 사며 주담대를 받으면 6개월 안에 전입해야 하고, 수도권 주담대 만기는 30년까지로 제한돼요. 생애최초 LTV는 70%예요.","tag":"대출 조건","title":"수도권 주담대 6개월 내 전입, 만기 30년","url":"https://www.fsc.go.kr/no010101/84824?srchCtgry=&curPage=&srchKey=&srchText=&srchBeginDt=&srchEndDt="},{"date":"2026-04-01","impact":"무주택 신혼부부에게 직접 걸리는 규제는 아니지만, 전세대출도 앞으로 DSR에 잡힐 수 있어 전세 후 매수 계획이면 소득 대비 부채를 여유 있게 잡는 게 좋아요.","source":"이투데이","summary":"다주택자·임대사업자의 수도권·규제지역 아파트 담보대출 만기연장을 4월 17일부터 원칙적으로 막았어요. 전세대출과 정책대출을 DSR 체계에 넣는 방안도 추진 중이에요.","tag":"가계부채","title":"2026년 가계부채 관리방안","url":"https://www.etoday.co.kr/news/view/2572759"},{"date":"2026-08-13","impact":"둘 다 30대 초중반이라면 은행에 장래소득 인정기준 적용을 요청해보세요. 신혼부부 소득 기준 완화가 어떤 상품에 적용되는지는 10월 시행 때 다시 확인이 필요해요.","source":"금융위원회 보도자료","summary":"가계대출 증가율 목표를 1.5%에서 3%로 올렸고, LTV·DSR 비율과 주택가격별 한도는 유지했어요. 생애최초 요건 합리화와 DSR 장래소득 인정기준 활성화는 8월 31일부터 시행됐어요. 신혼부부는 부부합산 소득이 8,500만원을 넘어도 한 사람 소득이 7천만원 이하면 대출을 받을 수 있도록 심사 기준을 고쳐 10월부터 적용할 예정이에요.","tag":"실수요 지원","title":"8·13 부동산 시장 안정을 위한 금융 종합대책","url":"https://fsc.go.kr/no010101/87517?curPage=&srchBeginDt=&srchCtgry=&srchEndDt=&srchKey=&srchText="},{"date":"2026-08-13","impact":"무주택으로 전세를 구한다면 해당 없어요.","source":"허프포스트코리아","summary":"수도권·규제지역 아파트를 가진 1주택 부부가 그 집에 산 적 없이 세를 주고 있다면 전세대출 보증이 제한돼요.","tag":"전세대출","title":"비거주 1주택자 전세대출 보증 제한","url":"https://www.huffingtonpost.kr/article/259568"},{"date":"2026-07-31","impact":"입주 후 출산 계획이 있다면 대환 시점에 다시 볼 만해요.","source":"KB의 생각","summary":"대출 신청일 기준 2년 안에 출산·입양한 무주택 가구가 대상이에요. 부부합산 소득 1억 3천만원 이하(맞벌이는 2억원), 9억원 이하·전용 85㎡ 이하 주택, 한도는 최대 4억원이에요.","tag":"정책대출","title":"신생아 특례 디딤돌","url":"https://kbthink.com/loan-guide/newborn-special.html"},{"date":"2026","impact":"분당·수지 시세라면 가격 기준 6억에 걸리는 경우가 많아요. 자금 탭에 자격 여부가 표시돼요.","source":"집품 블로그","summary":"부부합산 소득 8,500만원 이하, 순자산 약 5.1억원 이하 무주택 신혼가구가 6억원 이하 주택을 살 때 최대 3.2억원까지예요. 수도권 아파트는 방공제로 실제 한도가 줄 수 있어요.","tag":"정책대출","title":"신혼부부 디딤돌","url":"https://zippoom.com/블로그/신혼부부-디딤돌대출-소득-조건-금리-한도/375"},{"date":"2026-07","impact":"전세로 먼저 시작한다면 소득 기준부터 확인하세요. 상품 개편으로 한도가 바뀌었을 수 있어 기금e든든 조회가 필요해요.","source":"위키독스 정리글","summary":"혼인 7년 이내 또는 3개월 안 결혼 예정인 무주택 세대주, 부부합산 소득 7,500만원 이하, 순자산 3.45억원 이하가 대상이에요. 보증금의 80% 안에서 수도권 최대 3억원이에요.","tag":"정책대출","title":"신혼부부 전용 버팀목 전세자금","url":"https://wikidocs.net/blog/@Insight_Lab/26391/"},{"date":"2026-08-21","impact":"자금 탭 금리를 0.5~1%p 올려서도 계산해보고, 변동금리라면 월 상환 여유를 남겨두세요.","source":"KB주택시장 리뷰 2026년 8월호","summary":"한국은행 총재가 고물가 지속 가능성을 들며 금리 인상 필요성을 언급했고, 대출금리도 따라 오를 수 있다는 전망이 나와요.","tag":"금리","title":"하반기 금리 인상 가능성","url":"https://kbthink.com/realestate/insights/research/260819-7.html"}]$json$::jsonb,
  $json${"dsr":40,"ltv":{"local":70,"localFirst":80,"metro":70,"metroFirst":70,"reg":40,"regFirst":70},"maxTermMetro":30,"stress":{"local":0.75,"metro":3},"caps":[{"upTo":150000,"cap":60000},{"upTo":250000,"cap":40000},{"upTo":null,"cap":20000}],"programs":{"newborn":{"incomeSingle":13000,"incomeDual":20000,"priceMax":90000,"max":40000,"ltv":70},"didimNewly":{"income":8500,"priceMax":60000,"max":32000,"netAsset":51100,"ltv":70},"bogeum":{"income":7000,"priceMax":60000,"max":36000,"maxFirst":42000,"ltv":70},"butteokNewly":{"income":7500,"netAsset":34500,"maxMetro":30000,"maxLocal":20000,"ratio":80},"newbornJeonse":{"incomeSingle":13000,"incomeDual":20000,"depositMetro":50000,"max":24000,"ratio":80},"bankJeonse":{"ratio":80,"max":50000}}}$json$::jsonb,
